import React from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
const labels = {
  dashboard: "Overview",
  reports: "Reports queue",
  analytics: "Analytics",
  officers: "Officers",
};
const TopHeader = ({ onMenu, notify }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const page = location.pathname.split("/")[1] || "dashboard";
  return (
    <header className="topbar">
      <button className="hamburger" onClick={onMenu}>
        ☰
      </button>
      <div className="crumb">
        <Link to="/dashboard">Workspace</Link>
        <span>/</span>
        <b>{labels[page] || "Case details"}</b>
      </div>
      <div className="top-actions">
        <span className="live-indicator">
          <i /> Live updates
        </span>
        <button
          className="icon-button"
          onClick={() => notify("You’re all caught up")}
        >
          ♧<i className="notification-dot" />
        </button>
        <span className="top-divider" />
        <button className="top-user" onClick={() => navigate("/login")}>
          <span className="avatar small">TK</span>
          <span>Thoko Kalua</span>
          <span>⌄</span>
        </button>
      </div>
    </header>
  );
};
export default TopHeader;
